import numpy as np
import matplotlib.pyplot as plt

def generate_sin_signal(length, frequency):
    t = np.arange(length)
    signal = np.sin(2 * np.pi * frequency * t / length)
    return signal / np.max(np.abs(signal))

def generate_triangle_signal(length, frequency, amplitude):
    t = np.arange(length)
    signal = amplitude * (2 * np.abs((t / length - 0.5) % (1 / frequency) - 0.5) - 0.5)
    return signal / np.max(np.abs(signal))

def generate_ramp_signal(length, slope):
    t = np.arange(length)
    signal = slope * (t / length)
    return signal / np.max(np.abs(signal))

def generate_impulse_signal(length, positions):
    signal = np.zeros(length)
    signal[positions] = 1
    return signal

def generate_random_noise_signal(length, amplitude_range):
    signal = np.random.uniform(amplitude_range[0], amplitude_range[1], length)
    return signal / np.max(np.abs(signal))

def generate_constant_signal(length, constant_value):
    signal = np.full(length, constant_value)
    return signal

def generate_signals(N, length, frequencies, triangle_amplitude, ramp_slopes, impulse_positions, noise_amplitude_range, constant_values):
    signals = []

    for _ in range(N):
        sin_signal = generate_sin_signal(length, np.random.choice(frequencies))
        triangle_signal = generate_triangle_signal(length, np.random.choice(frequencies), triangle_amplitude)
        ramp_signal = generate_ramp_signal(length, np.random.choice(ramp_slopes))
        impulse_signal = generate_impulse_signal(length, np.random.choice(impulse_positions))
        noise_signal = generate_random_noise_signal(length, noise_amplitude_range)
        constant_signal = generate_constant_signal(length, np.random.choice(constant_values))

        stacked_signal = np.vstack((sin_signal, triangle_signal, ramp_signal, impulse_signal, noise_signal, constant_signal))
        signals.append(stacked_signal)

    return signals

%matplotlib inline
def plot_signals(signals, titles, num_random_signals):
    num_signals = len(signals)
    num_rows = signals[0].shape[0]
    num_plots = min(num_signals, num_random_signals)

    fig, axs = plt.subplots(num_plots, num_rows, figsize=(12, 8))
    fig.tight_layout()

    for i in range(num_plots):
        for j in range(num_rows):
            axs[i, j].plot(signals[i][j])
            axs[i, j].set_ylim(-1, 1)
            axs[i, j].set_xticks([])
            axs[i, j].set_yticks([])
            if i == 0:
                axs[i, j].set_title(titles[j])
            if j == 0:
                axs[i, j].set_ylabel(f"Signal {i + 1}")

    plt.show()

