func (s *GetUIConfigInfoService) GetUIConfigInfo(ctx context.Context, req *tv_cast_api.GetUIConfigInfoRequest) *tv_cast_api.GetUIConfigInfoResponse {
	appID, versionCode, currentEnv, err := s.checkAndParseParams(ctx, req)
