}

func (s *GetUIConfigInfoService) checkAndParseParams(ctx context.Context, req *tv_cast_api.GetUIConfigInfoRequest) (int32, string, string, error) {
	// 校验并获取通参中的 app_id
	appID := util.GetAppIDFromAGWUnifyArgs(req.AgwCommonParam)
	if appID <= 0 {
		return 0, "", "", fmt.Errorf("[GetUIConfigInfo] checkParams failed, illegal agw_common_param.app_id")
	}
	// 校验并获取通参中的版本号
	// 目前流量只有抖音 所以获取的都是抖音的版本号
	// 如果后续有其他app 可能需要取其他的字段
	versionCode := util.GetVersionCodeFromAGWCommonArgs(req.AgwCommonParam)
	if versionCode == "" {
		return 0, "", "", fmt.Errorf("[GetUIConfigInfo] checkParams failed, illegal agw_common_param.version_code")
	}
	currentEnv, _ := ctx.Value("K_ENV").(string)
	return appID, versionCode, currentEnv, nil
}

// 目前流量只有抖音1128
// 其他流量默认按照int64处理
func (s *GetUIConfigInfoService) getVersionCodeInt(versionCode string, appID int32) int64 {
	var versionCodeInt int64
	switch appID {
	case tv_tools_consts.APPIDDouyin:
		versionCodeInt = int64(s.dyVersionCodeToInt(versionCode))
	default:
		versionCodeInt, _ = strconv.ParseInt(versionCode, 10, 64)
	}
	return versionCodeInt
}

// 抖音的版本号转换
func (s *GetUIConfigInfoService) dyVersionCodeToInt(versionCode string) int {
	clientVersion := int(0)
	// 以.为分隔符，获取字符数组
	versionInfo := strings.Split(versionCode, ".")
	// 长度为1，说明为xxxxxx格式，直接返回
	if len(versionInfo) == 1 {
		clientVersion, _ := strconv.ParseInt(versionCode, 10, 0)
		return int(clientVersion)
	}
	// 获取高位版本号
	majorVersion, err := strconv.ParseInt(versionInfo[0], 10, 0)
	if err != nil {
		return 0
	}
	factor := 10
	if majorVersion > 9 {
		factor = 100
	}
	for _, value := range versionInfo {
		valueInt, err := strconv.ParseInt(value, 10, 0)
		if err != nil || valueInt > 99 {
			return 0
		}
		clientVersion = clientVersion*factor + int(valueInt)
		// "9.9.7"-->90+9-->990+7-->997
		// "10.0.1"-->1000+0-->100000+1-->100001
	}
	return clientVersion
}

