public class client {
    public static void main(String[] args) throws IOException {
        // 连接到服务器端
        Socket socket = new Socket("localhost", 8000);
        String username = null;
        boolean flag = false;
        while (!flag) {
            // 获取用户名和密码
            BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter writer = new PrintWriter(socket.getOutputStream());
            Scanner input = new Scanner(System.in);
            String msg = reader.readLine();
            System.out.print(msg);
            String name = input.nextLine();
            writer.println(name);
            writer.flush();
            msg = reader.readLine();
            System.out.print(msg);
            String pwd = input.nextLine();
            writer.println(pwd);
            writer.flush();
            msg = reader.readLine();
            System.out.println(msg);
            writer.print(name + "> ");
            writer.flush();
            if (msg.equals("登录成功！")) {
                username = name;
                flag = true;
            }
        }

        // 进入提示符下
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        PrintWriter writer = new PrintWriter(socket.getOutputStream());
        Scanner input = new Scanner(System.in);
        String cmd = reader.readLine();
        while (flag && !cmd.equalsIgnoreCase("exit")) {
            System.out.print(cmd);
            String request = input.nextLine();
            writer.println(request);
            writer.flush();
            if (request.startsWith("get")) {
                get(request.split(" ")[1], username, socket);
            }
            cmd = reader.readLine();
        }
        input.close();
        writer.close();
        reader.close();
        socket.close();
    }

    // 下载文件
    private static void get(String fileName, String username, Socket socket) throws IOException {
        File file = new File(username, fileName);
        if (file.exists()) {
            System.out.println(fileName + " 已经存在，请重新下载！");
            return;
        }
        FileOutputStream outputStream = new FileOutputStream(file);
        InputStream inputStream = socket.getInputStream();
        byte[] buffer = new byte[1024];
        int len;
        while ((len = inputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, len);
        }
        outputStream.close();
        System.out.println(fileName + " 下载成功！");
    }
}

