            int back = (front + size) % maximum;
            items[back] = o;
            size++;
        }
    }

    @Override
    public boolean isEmpty() {
        //use the size!
        return (size==0);
    }

    @Override
    public int size() {
        //use the size!
        return size;
    }

    @Override
    public Object front() {
        // First check if the queue is empty.
        // If it is, print an error message and return null,
        // otherwise return the item at the front.

        if (isEmpty()) {
            System.out.println("Stack Empty");
            return null;
        } else {
            return items[front];
        }
    }
}

public class ArrayStack implements Stack {
    //fields to represent our stack in an array

    //the array of items
    private Object[] items;

    //maximum capacity
    private int maximum;

    //pointer to the position of the top of the stack
    //this points to -1 when the stack is empty
    private int top;

    public ArrayStack(){
        //set the capacity to 20
        maximum = 20;

        //create the array
        items = new Object[maximum];

        //set the top to -1 as the stack is empty
        top = -1;
    }

    @Override
    public Object pop() {
        // First check if the stack is empty.
        // If it is, print an error message and return null,
        // otherwise, return the item the top is pointing to 
        // and decrement the top pointer
        if (isEmpty()) {
            System.out.println("Stack Empty");
            return null;
        } else {
            Object answer = items[top];
            top--;
            return answer;
        }
    }

    @Override
    public void push(Object o) {
        // First check if the array is full.
        // If it is, print an error message,
        // else increment the top and put the item in that space
        if (top == (maximum - 1)){
           System.out.println("Stack full");
        } else {
            top++;
            items[top] = o;
        }
    }

    @Override
    public boolean isEmpty() {
        // The stack is empty if the top is pointing to -1
        return (top == -1);
    }

    @Override
    public int size() {
        // The size of the stack can be calculated using the position of top
        return(top + 1);
    }

    @Override
    public Object top() {
        // First check if the stack is empty. 
        // If it is, print an error message and return null,
        // otherwise, return the item the top is pointing to. 
        if (isEmpty()) {
            System.out.println("Stack Empty");
            return null;
        } else {
            return items[top];
        }
    }
}

import java.util.ArrayList;

public class DiGraph
{
    protected int numberOfNodes;
    protected ArrayList<Integer>[] adjacencyList;

    /**
     * Constructor for a directed graphs with a number of nodes but no edges.
     * @param nodes the number of nodes in the graph
     */
    public DiGraph(int nodes) {
        //initialise the number of nodes
        numberOfNodes = nodes;
        //make the array of ArrayLists
        adjacencyList = new ArrayList [nodes];
        //go through each node and make a new ArrayList for that node
        for (int i = 0; i < nodes; i++) {
            adjacencyList[i] = new ArrayList<Integer>();
        }
    }

    /**
     * Add an edge between the two nodes given
     * @param fromNode the node the edge starts from
     * @param toNode the node that the edge goes to
     */
    public void addEdge(int fromNode, int toNode){
        adjacencyList[fromNode].add(toNode);
    }

    /**
     * Return the number of nodes in the graph
     * @return the number of nodes in the graph
     */
    public int getNumberOfNodes() {return numberOfNodes; }

    /**
     * Determine whether there is an edge between the two nodes given
     * @param fromNode the node the edge starts from
     * @param toNode the node that the edge goes to
     * @return true if there is an edge between fromNode and toNode, false otherwise
     */
    public boolean hasEdge(int fromNode, int toNode) {return adjacencyList[fromNode].contains(toNode); }

    /**
     * Print the adjacency list representation of the graph
     */
    public void printAdjacencyList(){
        System.out.println("Number of nodes = "+ numberOfNodes);
        for (int i = 0; i< adjacencyList.length; i++){
            System.out.print("Neighbours of " + i + " : ");
            for (Integer neighbour: adjacencyList[i]) {
                System.out.print(neighbour + " ");
            }
            System.out.println();
        }
    }
}

