// ZYLLockFreeQueue.h
#pragma once
#include <atomic>
#include “RTPPacket.h”

class ZYLLockFreeQueue {
public:
    ZYLLockFreeQueue();
    ~ZYLLockFreeQueue();

    bool Enqueue(const RTPPacket& value);
    bool Dequeue(RTPPacket& value);
    size_t size() const;

private:
    struct Node {
        RTPPacket packet;
        std::atomic<Node*> next;
    };

    std::atomic<Node*> head;
    std::atomic<Node*> tail;
    std::atomic<size_t> count;
};

// ZYLLockFreeQueue.cpp
#include “ZYLLockFreeQueue.h”

ZYLLockFreeQueue::ZYLLockFreeQueue() {
    Node* dummy = new Node;
    dummy->next.store(nullptr);
    head.store(dummy);
    tail.store(dummy);
    count.store(0);
}

ZYLLockFreeQueue::~ZYLLockFreeQueue() {
    while (head.load() != tail.load()) {
        Node* temp = head.load();
        head.store(head.load()->next.load());
        delete temp;
    }
    delete head.load();
}

bool ZYLLockFreeQueue::Enqueue(const RTPPacket& value) {
    Node* newNode = new Node;
    newNode->packet = value;
    newNode->next.store(nullptr);

    Node* curTail;
    do {
        curTail = tail.load();
    } while (!std::atomic_compare_exchange_weak(&tail, &curTail, newNode));
    curTail->next.store(newNode);
    count.fetch_add(1);
    return true;
}

bool ZYLLockFreeQueue::Dequeue(RTPPacket& value) {
    Node* curHead;
    Node* nextHead;
    do {
        curHead = head.load();
        nextHead = curHead->next.load();
        if (nextHead == nullptr) {
            return false;
        }
    } while (!std::atomic_compare_exchange_weak(&head, &curHead, nextHead));
    value = nextHead->packet;
    count.fetch_sub(1);
    delete curHead;
    return true;
}

size_t ZYLLockFreeQueue::size() const {
    return count.load();
}

// main.cpp
#include <iostream>
#include “ZYLLockFreeQueue.h”
#include <thread>
#include <chrono>

void producer(ZYLLockFreeQueue &queue) {
    for (int i = 0; i < 10; ++i) {
        RTPPacket packet{}; // 在这里填充 RTPPacket 的内容。
        if (queue.Enqueue(packet)) {
            std::cout << “生产者: 成功入队” << std::endl;
        } else {
            std::cout << “生产者: 入队失败” << std::endl;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

void consumer(ZYLLockFreeQueue &queue) {
    for (int i = 0; i < 10; ++i) {
        RTPPacket packet{};
        if (queue.Dequeue(packet)) {
            std::cout << “消费者: 成功出队” << std::endl;
        } else {
            std::cout << “消费者: 出队失败” << std::endl;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(150));
    }
}

int main() {
    ZYLLockFreeQueue queue;

    std::thread producerThread(producer, std::ref(queue));
    std::thread consumerThread(consumer, std::ref(queue));

    producerThread.join();
    consumerThread.join();

    std::cout << "队列剩余元素: " << queue.size() << std::endl;

    return 0;
}


