Entity Snake is
	PORT(CLK:IN STD_LOGIC;
		 SWUP:IN STD_LOGIC;
		 SWDN:IN STD_LOGIC;
		 SWRT:IN STD_LOGIC;
		 SWLF:IN STD_LOGIC;
		 H_Scan:Buffer STD_LOGIC_VECTOR(15 downto 0);
		 V_Scan:OUT STD_LOGIC_VECTOR(15 downto 0));
End Snake;

Architecture a of Snake is
	Type Arr is array(0 to 31)of STD_LOGIC_VECTOR(3 downto 0);
	Signal Vertical: STD_LOGIC_VECTOR(3 downto 0);
	Signal Dly: STD_LOGIC_VECTOR(19 downto 0);
	Signal Rdm: STD_LOGIC_VECTOR(7 downto 0);
	Signal FdNd: STD_LOGIC:='0';
	Signal GmEnd: STD_LOGIC:='0';
   Signal Score: integer:=0;
	Signal Len: integer:=8;
	Signal P_x: Arr;
	Signal P_y: Arr;
	Signal F_x: STD_LOGIC_VECTOR(3 downto 0);
	Signal F_y: STD_LOGIC_VECTOR(3 downto 0);
	Signal Dir: STD_LOGIC_VECTOR(1 downto 0):="11";
	Signal CLKS: STD_LOGIC;
BEGIN

Process(CLK)
Variable k: integer := 0;
	Begin
		if(CLK'Event and CLK='1')then
			if(Rdm="00000000")then
				Rdm<="00000001";
			else
				Rdm(0)<=Rdm(0) Xor Rdm(1) Xor Rdm(2) Xor Rdm(7);
				Rdm(1)<=Rdm(0);
				Rdm(2)<=Rdm(1);
				Rdm(3)<=Rdm(2);
				Rdm(4)<=Rdm(3);
				Rdm(5)<=Rdm(4);
				Rdm(6)<=Rdm(5);
				Rdm(7)<=Rdm(6);
			End if;
			if(SWUP='0')then
				Dir<="00";
			Elsif(SWDN='0')then
				Dir<="01";
			Elsif(SWLF='0')then
			   Dir<="10";
			Elsif(SWRT='0')then
				Dir<="11";
			End if;
			for k in 0 to Len-1 loop
				if(k<=Score and Score>1)then
					if(P_x(0)=P_x(k+1))then
						if(P_y(0)=P_y(k+1))then
							GmEnd<='1';
						End if;
					End if;
				End if;
			End loop;
		End if;
End Process;

Process(FdNd)
Variable l: integer :=0;
Variable Tr: STD_LOGIC :='1';
	Begin
		if(FdNd='1')then
			for l in 0 to Len loop
				if(l<=Score)then
					if(Rdm(7 downto 4)=P_x(l) and Rdm(3 downto 0)=P_y(l))then
						Tr:='0';
					End if;
				End if;
			End loop;
			if(Tr='1')then
				F_x<=Rdm(7 downto 4);
				F_y<=Rdm(3 downto 0);
			End if;
		End if;
End Process;

Process(CLK)
	Begin
		if(CLK'Event and CLK='1')then
			if(GmEnd='0')then
				Dly<=Dly+1;
				if(Dly="11111111111111111111")then
					CLKS<='0';
				Elsif(Dly="01111111111111111111")then
					CLKS<='1';
				End if;
			End if;
		End if;
End Process;

Process(CLKS)
Variable j: integer := 0;
	Begin
		if(CLKS'Event and CLKS='0')then
			for j in 0 to Len loop
				if(j<=Score)then
					P_x(j+1)<=P_x(j);
					P_y(j+1)<=P_y(j);
				End if;
			End loop;
			if(Dir="00")then
				P_y(0)<=P_y(0)+1;
			Elsif(Dir="01")then
				P_y(0)<=P_y(0)-1;
			Elsif(Dir="10")then
				P_x(0)<=P_x(0)-1;
			Elsif(Dir="11")then
				P_x(0)<=P_x(0)+1;
			End if;
		End if;
End Process;

Process(CLKS)
