		if(CLKS'Event and CLKS='1')then
			if(F_x=P_x(0) and F_y=P_y(0))then
				FdNd<='1';
				Score<=Score+1;
			Else
				FdNd<='0';
			End if;
		End if;
End Process;

Process(CLK)
