            float x = event.values[0];
            float y = event.values[1];
            float z = event.values[2];

            float rotation = (float) Math.sqrt(x * x + y * y + z * z);

            gyroscopeValues.add(rotation);
        } else if (event.sensor == stepCounterSensor) {
            // Increment step count
