如果多个摄像头设备都往一个端口推音视频流，会不会导致流处理不过来,可以将不同设备的流分发不同的线程处理，避免堵塞问题吗？请用c++实现这个分发流到过程，假设流是rtp包,请在StreamThread.h,StreamThread.cpp,main.cpp实现
好的，这里是一个简化的示例，它在不同的线程中处理来自不同摄像头设备的RTP数据包。我们将使用多线程和阻塞队列来处理RTP包。

1. 首先创建 StreamThread.h ，定义 StreamThread 类和 BlockingQueue 类：

#ifndef STREAMTHREAD_H
#define STREAMTHREAD_H

#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <deque>

template <typename T>
class BlockingQueue {
public:
    void push(const T& item) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            queue_.push_back(item);
        }
        cond_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        cond_.wait(lock, this { return !queue_.empty(); });
        T item = queue_.front();
        queue_.pop_front();
        return item;
    }

private:
    std::deque<T> queue_;
    std::mutex mutex_;
    std::condition_variable cond_;
};

class StreamThread {
public:
    StreamThread();
    ~StreamThread();

    void start();
    void stop();
    void addRtpPacket(const std::string& rtpPacket);

private:
    void process();
    bool running_;
    std::thread* thread_;
    BlockingQueue<std::string> rtpPackets_;
};

#endif // STREAMTHREAD_H


2. 然后，在 StreamThread.cpp 文件中实现 StreamThread 类：

#include “StreamThread.h”

StreamThread::StreamThread()
    : running_(false), thread_(nullptr) {
}

StreamThread::~StreamThread() {
    stop();
}

void StreamThread::start() {
    running_ = true;
    thread_ = new std::thread(&StreamThread::process, this);
}

void StreamThread::stop() {
    if (running_) {
        running_ = false;
        thread_->join();
        delete thread_;
    }
}

void StreamThread::addRtpPacket(const std::string& rtpPacket) {
    rtpPackets_.push(rtpPacket);
}

void StreamThread::process() {
    while (running_) {
        std::string rtpPacket = rtpPackets_.pop();

        if (!running_)
            break;

        // 在这里处理RTP包
        std::cout << "处理RTP包: " << rtpPacket << std::endl;
    }
}


