                                     + distance_to_a_X * (1 - distance_to_a_Y) * preData[original_point_C + 2]
                                     + distance_to_a_X * distance_to_a_Y * preData[original_point_D + 2];
            }
        }
    }


    fwrite(aftData, 1, LaterImg, targetFile);
    fclose(file);
    fclose(targetFile);

    return 0;
}

