axis.SetActive(true);
axis.transform.SetParent(selectedPart.transform);
axis.transform.localPosition = new Vector3(0, selectedPart.GetComponent<Renderer>().bounds.extents.x + 0.15f, 0);
axisOffset = selectedPart.transform.position - axis.transform.position;
mouseOffset = selectedPart.transform.position - Camera.main.ScreenToWorldPoint(Input.mousePosition);

}
else
{
if (selectedPart != null)
{
Destroy(outline);
selectedPart = null;
axis.SetActive(false);
}

}

}
if (Input.GetMouseButton(0) && selectedPart != null)
{
Vector3 mousePosition = Input.mousePosition;
mousePosition.z = axisOffset.z;
Vector3 worldMousePosition = Camera.main.ScreenToWorldPoint(mousePosition) + mouseOffset;
Vector3 localPosition = selectedPart.parent.InverseTransformPoint(worldMousePosition - axisOffset);
localPosition.x = axis.transform.localEulerAngles.y == 90 ? -localPosition.x : localPosition.x;
localPosition.y = axis.transform.localEulerAngles.x == 90 ? -localPosition.y : localPosition.y;
localPosition.z = axis.transform.localEulerAngles.y == 0 ? -localPosition.z : localPosition.z;
selectedPart.localPosition = new Vector3(Mathf.Round(localPosition.x * 10000) / 10000f, Mathf.Round(localPosition.y * 10000) / 10000f, Mathf.Round(localPosition.z * 10000) / 10000f);
}

}

private bool IsDescendant(Transform child, Transform parent)
{
foreach (Transform t in parent)
{
if (t == child)
return true;
if (IsDescendant(child, t))
return true;
}
return false;
}

private Transform GetClickedPart(Transform parent)
{
Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
RaycastHit hit;
if (Physics.Raycast(ray, out hit))
{
Transform clickedPart = hit.transform;
if (IsDescendant(clickedPart, parent))
{
return clickedPart;
}
}
return null;
}

public void ToggleControlEnabled()
{
isControlEnabled = !isControlEnabled;
animator.enabled = !animator.enabled;
}
}
