class queue {
private:
    Element *elements;
    int size = 0;
    int capacity = 10;
    int highestpriority() {
        int highest = 0;
        for (int i = 1; i < size; i++) {
            if (elements[highest].priority < elements[i].priority) {
                highest = i;
            }
        }
        return highest;
    }

public:
    queue() {
        elements = new Element[capacity];
    }
    ~queue() {
        for (int i = 0; i < size; i++) {
            delete[] &elements[i].priority;
        }
    }
    void enqueue(int priority, int value) {
        Element newel;
        newel.priority = priority;
        newel.value = value;
        int buffv, buffp, flag = 0;
        if (size + 1 > capacity) {
            capacity = 2;
            Element *newElements = new Element[capacity];
            for (int i = 0; i < size; i++) {
                newElements[i] = elements[i];
            }
            delete[] elements;
            elements = newElements;
        }
        elements[size] = newel;
        size++;
        for (int i = size - 2; i > -1; i--) {
            if (flag == 0) {
                if ((elements[i].priority > elements[size - 1].priority)) {
                    flag = 1;
                } else {
                    if ((i == 0) && (elements[i].priority < elements[size - 1].priority)) {
                        for (int j = size - 1; j > i; j--) {
                            buffv = elements[j].value;
                            buffp = elements[j].priority;
                            elements[j].value = elements[j - 1].value;
                            elements[j].priority = elements[j - 1].priority;
                            elements[j - 1].value = buffv;
                            elements[j - 1].priority = buffp;
                            flag = 1;
                        }
                    }
                    if ((elements[i].priority < elements[size - 1].priority) &&
(elements[i - 1].priority > elements[size - 1].priority)) {
                        for (int j = size - 1; j > i; j--) {
                            buffv = elements[j].value;
                            buffp = elements[j].priority;
                            elements[j].value = elements[j - 1].value;
                            elements[j].priority = elements[j - 1].priority;
                            elements[j - 1].value = buffv;
                            elements[j - 1].priority = buffp;
                            flag = 1;
                        }
                    }
                    if ((elements[i].priority == elements[size - 1].priority)) {
                        for (int j = size - 1; j > i + 1; j--) {
                            buffv = elements[j].value;
                            buffp = elements[j].priority;
                            elements[j].value = elements[j - 1].value;
                            elements[j].priority = elements[j - 1].priority;
                            elements[j - 1].value = buffv;
                            elements[j - 1].priority = buffp;
                            flag = 1;
                        }
                    }
                }
            }
        }
    }
    Element wthdrw(int index) {
