                                UTILITIES
    //////////////////////////////////////////////////////////////*/


    /// @notice Returns the square root of a number.
    function sqrt(uint256 x) private pure returns (uint256) {
        uint256 z = (x + 1) / 2;
        uint256 y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
        return y;
    }

    /// @notice Returns the minimum of two numbers.
