void MainWindow::showPicture()
{
// Remove any existing object in the scene
if(object != nullptr)
scene->removeItem(object);

// Add a rectangle
QGraphicsRectItem *rectangle = new QGraphicsRectItem(-50, -50, 100, 100);
rectangle->setBrush(Qt::red);
