void MainWindow::choose()
{
// Create a dialog to get the speed and direction input
QDialog *dialog = new QDialog(this);
dialog->setWindowTitle("Choose options");

speedInput = new QLineEdit(dialog);
speedInput->setPlaceholderText("Enter speed (pixels per second)");

directionButtons = new QButtonGroup(dialog);
QRadioButton *upButton = new QRadioButton("Up-Down");
QRadioButton *leftRightButton = new QRadioButton("Left-Right");
directionButtons->addButton(upButton, 0);
directionButtons->addButton(leftRightButton, 1);

QPushButton *okButton = new QPushButton("OK");
connect(okButton, &QPushButton::clicked, dialog, &QDialog::accept);

QVBoxLayout *layout = new QVBoxLayout(dialog);
layout->addWidget(speedInput);
layout->addWidget(upButton);
layout->addWidget(leftRightButton);
layout->addWidget(okButton);

if(dialog->exec() == QDialog::Accepted)
{
// Get the speed and direction input
speed = speedInput->text().toInt();
direction = directionButtons->checkedId();
}

// Clean up the dialog
delete speedInput;
delete directionButtons;
delete dialog;
}


void MainWindow::animate()
{
if(timer == nullptr)
{
// Create a timer to animate the object
timer = new QTimer(this);
connect(timer, &QTimer::timeout, this, &MainWindow::moveObject);
}

// Start the timer with the specified speed and direction
if(direction == 0)
object->setPos(0, -50);
else
object->setPos(-50, 0);

timer->start(1000.0 / speed);
}




void MainWindow::moveObject()
{
qreal x = object->x();
qreal y = object->y();

// Move the object in the specified direction
if(direction == 0)
y += 1;
else
x += 1;

// Reverse direction when reaching the edge of the scene
if(x >= scene->width() - object->boundingRect().width() || x <= 0)
direction = 1 - direction;

if(y >= scene->height() - object->boundingRect().height() || y <= 0)
direction = 1 - direction;

// Set the new position of the object
object->setPos(x, y);
}



void MainWindow::stop()
{
if(timer != nullptr)
{
// Stop the timer
timer->stop();

// Reset the direction and speed
direction = 0;
speed = 0;
}
}

