#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_N 10
#define MAX_L 100

int n; // 变量数
char vars[MAX_N]; // 变量名
char expr[MAX_L]; // 表达式
bool vals[1 << MAX_N][MAX_N + 1]; // 真值表

// 计算逻辑表达式的值
bool calc(char *expr, bool *val) {
    int len = strlen(expr);
    int i, j;
    char c;

    bool stack[MAX_L], res;
    int top = -1;

    for (i = 0; i < len; ++i) {
        c = expr[i];
        if (c >= 'a' && c <= 'z') {
            for (j = 0; j < n; ++j) {
                if (vars[j] == c) {
                    stack[++top] = val[j];
                    break;
                }
            }
        } else if (c == '!') {
            stack[top] = !stack[top];
        } else if (c == '^') {
            bool b = stack[top--];
            bool a = stack[top--];
            stack[++top] = a && b;
        } else if (c == '|') {
            bool b = stack[top--];
            bool a = stack[top--];
            stack[++top] = a || b;
        } else if (c == '-') {
            bool b = stack[top--];
            bool a = stack[top--];
            stack[++top] = !a || b;
        } else if (c == '<') {
            bool b = stack[top--];
            bool a = stack[top--];
            stack[++top] = (!a || b) && (!b || a);
        } else {
            // do nothing
        }
    }

    res = stack[0];
    return res;
}

// 生成真值表
void generate() {
    int i, j, k;

    for (i = 0; i < (1 << n); ++i) {
        for (j = 0; j < n; ++j) {
            vals[i][j] = (i >> j) & 1;
        }
        vals[i][n] = calc(expr, vals[i]);
    }
}

// 输出真值表
void output() {
    int i, j;

    for (i = 0; i < n; ++i) {
        printf("%c ", vars[i]);
    }
    printf("%s
", expr);

    for (i = 0; i < (1 << n); ++i) {
        for (j = 0; j <= n; ++j) {
            printf("%d ", vals[i][j]);
        }
        printf("
");
    }
}

int main() {
    while (~scanf("%s", expr)) {
        int len = strlen(expr);
        int i, j;

        // 解析变量名和变量数
        n = 0;
        memset(vars, 0, sizeof(vars));
        for (i = 0; i < len; ++i) {
            if (expr[i] >= 'a' && expr[i] <= 'z') {
                bool found = false;
                for (j = 0; j < n; ++j) {
                    if (vars[j] == expr[i]) {
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    vars[n++] = expr[i];
                }
            }
        }

        generate();
        output();
    }

    return 0;
}
