                task();
            }
        });
    }

    template <typename F, typename... Args>
    auto submit(F&& f, Args&&... args)-> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(std::bind(std::forward<F>(f), std::forward<Args>(args)...));

        std::future<return_type> result = task->get_future();
        {
            std::unique_lock<std::mutex> lock(_mutex);
            if (_stop) {
                throw std::runtime_error("Submit on stopped ZYLThreadPool");
            }
            if (_taskQueue.size() >= worker_threads.size() && worker_threads.size() < _maxThreads) {
                create_thread();
            }
            _taskQueue.emplace_back([task] { (*task)(); });
        }
        _condVar.notify_one();
        return result;
    }

    void cancel() {
        std::unique_lock<std::mutex> lock(_mutex);
        if (!_stop) {
            _stop = true;
            _condVar.notify_all();
        }
        for (std::thread& worker : worker_threads)
            worker.join();
    }

    size_t getNumTasks() {
        std::unique_lock<std::mutex> lock(_mutex);
        return _taskQueue.size();
    }

    ~ZYLThreadPool() {
        cancel();
    }

private:
    std::vector<std::thread> worker_threads;
    std::deque<std::function<void()>> _taskQueue;
    size_t _minThreads;
    size_t _maxThreads;
    std::mutex _mutex;
    std::condition_variable _condVar;
    bool _stop;
};

class Test {
public:
    Test(double devid)
        : _devid(devid)
        , _running(true) {
    }

    void start(ZYLThreadPool& threadPool) {
        _future = threadPool.submit(&Test::_task, this);
    }

    void stop() {
        {
            _running = false;
            std::unique_lock<std::mutex> lock(_mutex);

            if (_future.valid()) {
                _future.get();
                lock.unlock();
                _cleanupResources();
            }
        }
    }

private:
    std::mutex _mutex;
    double _devid;
    std::deque<double> _dequeue_packets;
    std::future<void> _future;
    bool _running;

    void _cleanupResources() {
        std::unique_lock<std::mutex> lock(_mutex);
        _dequeue_packets.clear();
    }

    void _task() {
        std::unique_lock<std::mutex> lock(_mutex);
        while (_running) {
            if (_dequeue_packets.empty()) {
                //std::cout << "running task"<< std::endl;
                continue;
            }
            double packet = _dequeue_packets.front();
            _dequeue_packets.pop_front();
            lock.unlock();
            std::cout << "running task" << std::endl;
            lock.lock();
        }
		std::cout<<"task end"<<std::endl;
    }
};

