<script>
import qtContent from "@/components/qtContent";
import qtAddshop from "./qtAddshop.vue";
import qtEditshop from "./qtEditshop.vue";

export default {
  data() {
    return {
      title: "购物车",
      author: "",
      dataArr: [],
      modalDel: false,
      delId: "",
      api: this.api,
      showDialogVis: false,
      showedit: false,
    };
  },
  created() {
    let user = JSON.parse(sessionStorage.getItem("user"));
    this.author = user["userId"];
    this.getSelfshop();
  },
  components: {
    qtContent,
    qtAddshop,
    qtEditshop,
  },
  inject: ["reload"],
  methods: {
    setAllShopping() {
      const arr = this.dataArr.map(element => {
        return {
          id: element.id,
          userId: this.author,
        }
      });
      this.$http.orderPay(arr).then((resp) => {
        if (resp.code == "200") {
          this.$message.success("购买成功");
          this.getSelfshop();
        }
      });
    },
    getCookie(name) {
      var value = "; " + document.cookie;
      var parts = value.split("; " + name + "=");
      if (parts.length === 2) return parts.pop().split(";").shift();
    },
    getSelfshop() {
      this.$http.cartshop(this.author).then((resp) => {
        if (resp.code == "200") {
          this.dataArr = resp.rows;
          console.log(" this.dataArr", this.dataArr);
        }
      });
    },
    goshopDetailPage(id) {
      this.$router.push({
        name: "Details",
        query: { shopId: id },
      });
    },
    showModal(id) {
      this.modalDel = true;
      this.delId = id;
    },
    handleDelshop() {
      this.$http.delshop(this.delId, this.author).then((resp) => {
        if (resp.code == "200") {
          this.modalDel = false;
          this.$message.success("删除成功");
          this.delId = "";
          this.getSelfshop();
        }
      });
    },
    payShopping(id) {
      this.$http.orderPay([{
        id,
        userId: this.author
      }
      ]).then((resp) => {
        if (resp.code == "200") {
          this.$message.success("购买成功");
          this.getSelfshop();
        }
      });
    },
    goEditPage(id) {
      this.showedit = true;
      setTimeout(() => {
        this.$refs.qtEditshopRef.init(id);
      });
    },
  },
  filters: {
    capitalize(value) {
      if (!value) return "";
      if (value.length > 200) {
        return value.slice(0, 200) + "...";
      }
      return value;
    },
  },
};
</script>

