    private val depend: ICastSourceUIDepend,
    private val screenMode: ScreenMode?
) : AbsCastSourcePluginLoadingDialog(context, controller, depend) {

    companion object {
        private const val TAG = "LVCastSourcePluginLoadingDialog"
    }

    private var hasLoggedPageShow: Boolean = false  // 是否上报过page_show埋点

    override fun getLayout(): Int {
        return if (screenMode == ScreenMode.PORTRAIT) {
            R.layout.sourceui_activity_plugin_loading
        } else {
            R.layout.sourceui_activity_plugin_landscape_loading
        }
    }

    override fun getContentFl(): FrameLayout = findViewById(R.id.content_fl)

    override fun getPluginLoadingView(): AbsCastSourcePluginLoadingView {
        return DYFeedCastPluginLoadingView(context, depend = depend, screenMode = screenMode)
    }

    override fun showSearchView() {
        val searchView = if (screenMode == ScreenMode.PORTRAIT) {
            controller?.getCastSearchView(context, object: CastSourceUIDependWrapper(depend) {
                override fun onSearchPageClose(context: Context?, isLandscape: Boolean, action: Int) {
                    try {
                        if (isShowing) dismiss()
                    } catch (e: Exception) {
                        CastSourceUILog.e(TAG, "dismiss dialog error: $e")
                    }
                    super.onSearchPageClose(context, isLandscape, action)
                }
            })
        } else {
            controller?.getCastLandscapeSearchView(context, object: CastSourceUIDependWrapper(depend) {
                override fun onSearchPageClose(context: Context?, isLandscape: Boolean, action: Int) {
                    try {
                        if (isShowing) dismiss()
                    } catch (e: Exception) {
                        CastSourceUILog.e(TAG, "dismiss dialog error: $e")
                    }
                    super.onSearchPageClose(context, isLandscape, action)
                }
            })
        }

        showSearchView(searchView)
    }

    override fun onWindowFocusChanged(hasFocus: Boolean) {
        super.onWindowFocusChanged(hasFocus)
        if (hasFocus) {
            if (screenMode == ScreenMode.LANDSCAPE) {
                window?.setGravity(Gravity.RIGHT)
                window?.setLayout(
                    ViewGroup.LayoutParams.WRAP_CONTENT,
                    ViewGroup.LayoutParams.MATCH_PARENT
                )
            }
        }
    }

    override fun onStart() {
        super.onStart()
        window?.let {
            it.setBackgroundDrawable(ColorDrawable(0x00000000))
            it.setDimAmount(0F)     // 去掉蒙层
            if (screenMode == ScreenMode.LANDSCAPE) {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                    it.setFlags(WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS, WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS)
                }
                it.setWindowAnimations(R.style.sourceui_right_dialog_anim)
                it.setGravity(Gravity.RIGHT)
                it.setLayout(
                    ViewGroup.LayoutParams.WRAP_CONTENT,
                    ViewGroup.LayoutParams.MATCH_PARENT
                )
            } else {
                it.setWindowAnimations(R.style.sourceui_bottom_dialog_anim)
                val height = depend?.getSearchViewTargetHeight() ?: context.dip2Px(528F).toInt()
                it.setGravity(Gravity.BOTTOM)
                it.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, height)
            }
        }
        if (!hasLoggedPageShow) {
            hasLoggedPageShow = true
            CastSourceUIApiAppLogEvent.sendPluginPageShow(depend, screenMode == ScreenMode.LANDSCAPE)
        }
    }
